// NULL-tolerant scan buffer for accountMovementScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type accountMovementPreloadBuf struct {
	ID            sql.Null[uuid.UUID]
	HouseholdID   sql.Null[uuid.UUID]
	JournalID     sql.Null[uuid.UUID]
	Kind          sql.Null[string]
	OccurredAt    sql.Null[time.Time]
	FromAccountID sql.Null[uuid.UUID]
	ToAccountID   sql.Null[uuid.UUID]
	AmountYen     sql.Null[int64]
	Description   sql.Null[string]
	CreatedAt     sql.Null[time.Time]
}

// accountMovementScanMapperNullable maps the preloaded accountMovement
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func accountMovementScanMapperNullable(prefix string) scan.Mapper[*AccountMovement] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*AccountMovement, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *accountMovementPreloadBuf) any
		}
		targets := make([]target, 0, 10)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.HouseholdID }})
			case "journal_id":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.JournalID }})
			case "kind":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.Kind }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.OccurredAt }})
			case "from_account_id":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.FromAccountID }})
			case "to_account_id":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.ToAccountID }})
			case "amount_yen":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.AmountYen }})
			case "description":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.Description }})
			case "created_at":
				targets = append(targets, target{i, func(b *accountMovementPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(accountMovementPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*AccountMovement, error) {
				buf := link.(*accountMovementPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.JournalID.Valid) &&
					!(buf.Kind.Valid) &&
					!(buf.OccurredAt.Valid) &&
					!(buf.FromAccountID.Valid) &&
					!(buf.ToAccountID.Valid) &&
					!(buf.AmountYen.Valid) &&
					!(buf.Description.Valid) &&
					!(buf.CreatedAt.Valid) {
					return nil, nil
				}

				o := new(AccountMovement)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.JournalID.Valid {
					o.JournalID = buf.JournalID.V
				}
				if buf.Kind.Valid {
					o.Kind = buf.Kind.V
				}
				if buf.OccurredAt.Valid {
					o.OccurredAt = buf.OccurredAt.V
				}
				if buf.FromAccountID.Valid {
					o.FromAccountID = buf.FromAccountID.V
				}
				if buf.ToAccountID.Valid {
					o.ToAccountID = buf.ToAccountID.V
				}
				if buf.AmountYen.Valid {
					o.AmountYen = buf.AmountYen.V
				}
				if buf.Description.Valid {
					o.Description = buf.Description.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				return o, nil
			}
	}
}

func (o *AccountMovement) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("accountMovement cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.AccountMovements = AccountMovementSlice{o}
		}
		return nil
	case "Journal":
		rel, ok := retrieved.(*Journal)
		if !ok {
			return fmt.Errorf("accountMovement cannot load %T as %q", retrieved, name)
		}

		o.R.Journal = rel
		o.R.Loaded.Journal = true

		if rel != nil {
			rel.R.AccountMovement = o
			rel.R.Loaded.AccountMovement = true
		}
		return nil
	case "DocumentConfirmations":
		rels, ok := retrieved.(DocumentConfirmationSlice)
		if !ok {
			return fmt.Errorf("accountMovement cannot load %T as %q", retrieved, name)
		}

		o.R.DocumentConfirmations = rels
		o.R.Loaded.DocumentConfirmations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.AccountMovement = o
				rel.R.Loaded.AccountMovement = true
			}
		}
		return nil
	default:
		return fmt.Errorf("accountMovement has no relationship %q", name)
	}
}

type accountMovementPreloader struct {
	Household func(...psql.PreloadOption) psql.Preloader
	Journal   func(...psql.PreloadOption) psql.Preloader
}

func buildAccountMovementPreloader() accountMovementPreloader {
	return accountMovementPreloader{
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        AccountMovements,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
		Journal: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Journal, JournalSlice](psql.PreloadRel{
				Name: "Journal",
				Sides: []psql.PreloadSide{
					{
						From:        AccountMovements,
						To:          Journals,
						FromColumns: []string{"journal_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Journals.Columns.Names(), journalScanMapperNullable, opts...)
		},
	}
}

