// LoadHousehold loads the accountMovement's Household into the .R struct
func (o *AccountMovement) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AccountMovements = AccountMovementSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the accountMovement's Household into the .R struct
func (os AccountMovementSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	accountMovementByKey := make(map[uuid.UUID][]*AccountMovement, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		accountMovementByKey[o.HouseholdID] = append(accountMovementByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := accountMovementByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.AccountMovements = append(rel.R.AccountMovements, o)

			o.R.Household = rel

		}
	}

	return nil
}

